  const items = Array.from(document.querySelectorAll('div[jscontroller]')).filter(el => {
    return el.querySelector('h2') && el.innerText && el.innerText.includes('$');
  });

  return items.map(el => {
    const name = el.querySelector('h2')?.innerText || "";
    const text = el.innerText || "";
    // Rating match e.g. 4.5 or 4.6
    const ratingMatch = text.match(/([3-5]\.[0-9])\s*\/\s*5/);
    const starMatch = text.match(/([3-5]\.[0-9])\s*(?:\([0-9,.]+[KM]?\))/);
    const priceMatch = text.match(/\$([0-9,]+)/);
    const stars = ratingMatch ? ratingMatch[1] : (starMatch ? starMatch[1] : null);
    return {
      name,
      rating: stars,
      price: priceMatch ? priceMatch[1] : null,
      fullSnippet: text.slice(0, 300).replace(/\n+/g, ' | ')
    };
  }).filter(h => h.name && h.price);
});

