const tabId = 2136412315;

const res = await browserjs(tabId, () => {
  // Check for any survey popup or close buttons
  const closeSurvey = document.querySelector('button[aria-label="Close"], button[aria-label="Dismiss"], .scSurveyContainer button');
  if (closeSurvey) closeSurvey.click();

  // Find check-in and check-out inputs or calendar buttons
  // Look for Done button
  const doneButtons = Array.from(document.querySelectorAll('button')).filter(b => b.innerText && b.innerText.trim() === 'Done');

  // Find December 26 button in calendar
  const dec26 = Array.from(document.querySelectorAll('button[aria-label*="December 26, 2026"], [data-iso="2026-12-26"]')).find(b => b);
  if (dec26) {
    dec26.click();
  }

  // Click done
  if (doneButtons.length > 0) {
    doneButtons[doneButtons.length - 1].click();
  }
  return { hasSurvey: !!closeSurvey, hasDec26: !!dec26, doneCount: doneButtons.length };
});

console.log("Calendar interaction:", res);
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 5000 });

