  const inputs = Array.from(document.querySelectorAll('input[type="text"], [role="textbox"]')).map(i => ({
    ariaLabel: i.getAttribute('aria-label'),
    value: i.value || i.innerText
  }));
  return {
    url: window.location.href,
    inputs
  };
});
console.log("Current inputs:", JSON.stringify(dates, null, 2));

