const tabId = 2136412315;

const pickDates = await browserjs(tabId, () => {
  // Find Dec 23
  const allElements = Array.from(document.querySelectorAll('*'));
  const dec23 = allElements.find(el => el.getAttribute('aria-label')?.includes('Wednesday, December 23, 2026'));
  const dec26 = allElements.find(el => el.getAttribute('aria-label')?.includes('Saturday, December 26, 2026'));

  if (!dec23 || !dec26) return { error: "Dates not found", has23: !!dec23, has26: !!dec26 };

  // Scroll into view and click dec23
  dec23.scrollIntoView({ block: "center" });
  dec23.click();

  // Scroll into view and click dec26
  dec26.scrollIntoView({ block: "center" });
  dec26.click();

  // Find Done button
  const doneBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText && b.innerText.trim() === 'Done');
  if (doneBtn) {
    doneBtn.click();
    return { success: true, clickedDone: true };
  }
  return { success: true, clickedDone: false };
});

console.log("Pick dates result:", pickDates);
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 5000 });

