  const inputs = Array.from(document.querySelectorAll('input')).map(i => ({
    ariaLabel: i.getAttribute('aria-label'),
    value: i.value
  }));
  return {
    url: window.location.href,
    inputs
  };
});
console.log("Verification:", JSON.stringify(verification, null, 2));

